WITH valid AS (SELECT *, CAST(amount AS INT) AS amount_int, IF(is_flagged, 'Yes', 'No') AS is_flagged_label, COALESCE(merchant, 'N/A') AS resolved_merchant FROM transactions WHERE merchant IS NOT NULL) SELECT id, merchant, DENSE_RANK() OVER (ORDER BY amount DESC NULLS FIRST) AS amount_dense_rank, COUNT(amount) OVER (PARTITION BY account_id, merchant ORDER BY CAST(txn_time AS BIGINT) RANGE BETWEEN 7776000 PRECEDING AND CURRENT ROW) AS amount_count_90d FROM valid WHERE merchant NOT IN ('Shell', 'Starbucks', 'Lazada')
